toolScript:
// --- Audio Engine Variables ---
        let audioCtx;
        let oscillator;
        let gainL, gainR;
        let delayL, delayR;
        let merger;
        let isTesting = false;
        // --- Test Configuration ---
        const testStages = [
            { freq: 250, label: "Stage 1: Baseline Coherence" },
            { freq: 100, label: "Stage 2: Mid-Bass Isolation" },
            { freq: 40, label: "Stage 3: Sub-Bass Integrity" }
        ];
        let currentStage = 0;
        let userOffsets = [];
        // --- DOM Elements ---
        const introScreen = document.getElementById('intro-screen');
        const testScreen = document.getElementById('test-screen');
        const resultScreen = document.getElementById('result-screen');
        const freqVal = document.getElementById('freq-val');
        const testLabel = document.getElementById('test-label');
        const slider = document.getElementById('phase-slider');
        const statusDot = document.getElementById('status-dot');
        const statusText = document.getElementById('status-text');
        function initAudio() {
            if (!audioCtx) {
                audioCtx = new (window.AudioContext || window.webkitAudioContext)();
                // Create Nodes
                oscillator = audioCtx.createOscillator();
                oscillator.type = 'sine';
                gainL = audioCtx.createGain();
                gainR = audioCtx.createGain();
                delayL = audioCtx.createDelay(1.0); // max 1 second delay
                delayR = audioCtx.createDelay(1.0);
                merger = audioCtx.createChannelMerger(2);
                // Routing Left
                oscillator.connect(delayL);
                delayL.connect(gainL);
                gainL.connect(merger, 0, 0);
                // Routing Right
                oscillator.connect(delayR);
                delayR.connect(gainR);
                gainR.connect(merger, 0, 1);
                // Master Out
                merger.connect(audioCtx.destination);
                // Start Oscillator silently
                gainL.gain.value = 0;
                gainR.gain.value = 0;
                oscillator.start();
            }
            // Resume context if suspended by browser policy
            if (audioCtx.state === 'suspended') {
                audioCtx.resume();
            }
        }
        function startCalibration() {
            initAudio();
            isTesting = true;
            currentStage = 0;
            userOffsets = [];
            introScreen.classList.add('hidden');
            testScreen.classList.remove('hidden');
            statusDot.classList.replace('bg-slate-300', 'bg-blue-500');
            statusDot.classList.add('animate-pulse');
            statusText.innerText = "Transmitting Signal";
            statusText.classList.replace('text-slate-500', 'text-blue-500');
            loadStage(currentStage);
        }
        function loadStage(index) {
            const stage = testStages[index];
            freqVal.innerText = stage.freq;
            testLabel.innerText = stage.label;
            // Reset Slider to 0
            slider.value = 0;
            updatePhase(0);
            // Set Oscillator Frequency
            oscillator.frequency.setTargetAtTime(stage.freq, audioCtx.currentTime, 0.05);
            // Ramp up volume
            gainL.gain.setTargetAtTime(0.5, audioCtx.currentTime, 0.1);
            gainR.gain.setTargetAtTime(0.5, audioCtx.currentTime, 0.1);
            // Update Stepper UI
            document.querySelectorAll('.step-dot').forEach((dot, i) => {
                dot.className = 'step-dot'; // reset
                if (i < index) dot.classList.add('completed');
                else if (i === index) dot.classList.add('active');
            });
        }
        function updatePhase(val) {
            if (!audioCtx) return;
            // Slider range is -100 to +100
            // We map this to a max delay of 0.8ms (0.0008 seconds) which is roughly human max ITD
            const maxDelay = 0.0008;
            const value = parseFloat(val);
            if (value < 0) {
                // Pan Left: Delay Right, attenuate Right slightly
                delayL.delayTime.value = 0;
                delayR.delayTime.value = (Math.abs(value) / 100) * maxDelay;
                gainL.gain.value = 0.5;
                gainR.gain.value = 0.5 - (Math.abs(value) / 100) * 0.2; // mild amplitude panning
            } else {
                // Pan Right: Delay Left, attenuate Left slightly
                delayR.delayTime.value = 0;
                delayL.delayTime.value = (Math.abs(value) / 100) * maxDelay;
                gainR.gain.value = 0.5;
                gainL.gain.value = 0.5 - (Math.abs(value) / 100) * 0.2;
            }
        }
        function confirmCenter() {
            // Save current slider offset
            userOffsets.push(parseFloat(slider.value));
            // Ramp down volume momentarily to prevent clicking
            gainL.gain.setTargetAtTime(0, audioCtx.currentTime, 0.05);
            gainR.gain.setTargetAtTime(0, audioCtx.currentTime, 0.05);
            setTimeout(() => {
                currentStage++;
                if (currentStage < testStages.length) {
                    loadStage(currentStage);
                } else {
                    finishCalibration();
                }
            }, 200);
        }
        function finishCalibration() {
            isTesting = false;
            // Shut off audio
            if (gainL && gainR) {
                gainL.gain.value = 0;
                gainR.gain.value = 0;
            }
            statusDot.classList.remove('animate-pulse');
            statusDot.classList.replace('bg-blue-500', 'bg-emerald-500');
            statusText.innerText = "Analysis Complete";
            statusText.classList.replace('text-blue-500', 'text-emerald-500');
            testScreen.classList.add('hidden');
            resultScreen.classList.remove('hidden');
            calculateResults();
        }
        function calculateResults() {
            // We have 3 offsets for 250Hz, 100Hz, 40Hz
            const o250 = userOffsets[0];
            const o100 = userOffsets[1];
            const o40 = userOffsets[2];
            // Baseline is what they consider "center" anatomically at 250Hz
            // Variance is how far they had to drift to maintain center at lower frequencies
            const drift100 = Math.abs(o100 - o250);
            const drift40 = Math.abs(o40 - o250);
            // Max possible drift is roughly 200 (if they went from -100 to +100)
            // But realistically a drift > 30 is a massive seal failure
            const maxObservedDrift = Math.max(drift100, drift40);
            let score = 100 - (maxObservedDrift * 1.5);
            if (score < 0) score = 0;
            if (score > 100) score = 100;
            score = Math.round(score);
            // UI Updates
            const scoreDisplay = document.getElementById('score-display');
            const scoreVerdict = document.getElementById('score-verdict');
            const resultsLog = document.getElementById('results-log');
            scoreDisplay.innerText = score + "%";
            if (score >= 90) {
                scoreDisplay.className = "text-6xl font-black mb-2 tracking-tighter text-emerald-500";
                scoreVerdict.innerText = "Excellent Phase Coherence (Perfect Seal)";
            } else if (score >= 70) {
                scoreDisplay.className = "text-6xl font-black mb-2 tracking-tighter text-amber-500";
                scoreVerdict.innerText = "Minor Bass Leak Detected";
            } else {
                scoreDisplay.className = "text-6xl font-black mb-2 tracking-tighter text-red-500";
                scoreVerdict.innerText = "Severe Leak / Isolation Asymmetry";
            }
            // Populate Log
            resultsLog.innerHTML = `
                <li class="flex justify-between border-b border-slate-100 pb-2">
                    <span>250Hz Offset (Baseline):</span>
                    <span class="font-bold text-slate-800">${o250 > 0 ? '+' + o250 : o250}</span>
                </li>
                <li class="flex justify-between border-b border-slate-100 pb-2">
                    <span>100Hz Offset:</span>
                    <span class="font-bold text-slate-800">${o100 > 0 ? '+' + o100 : o100} <span class="text-xs text-slate-400 font-normal">(&Delta; ${drift100})</span></span>
                </li>
                <li class="flex justify-between">
                    <span>40Hz Offset:</span>
                    <span class="font-bold text-slate-800">${o40 > 0 ? '+' + o40 : o40} <span class="text-xs text-slate-400 font-normal">(&Delta; ${drift40})</span></span>
                </li>
            `;
        }
        // --- Scroll Logic ---
